def transform(grid):
    h, w = len(grid), len(grid[0])

    # The grid is a regular lattice of 4-by-5 tiles. Read the lattice
    # intersections as pixels, translating the ordinary separator color
    # into the tile's interior/background color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    # The most frequent color is the tile fill; the next most frequent is
    # the separator color.
    ordered = sorted(counts, key=counts.get, reverse=True)
    fill = ordered[0]
    separator = ordered[1]

    out = []
    for r in range(0, h, 4):
        row = []
        for c in range(0, w, 5):
            if c >= w:
                break
            value = grid[r][c]
            row.append(fill if value == separator else value)
        out.append(row)

    # Lattice samples at the far edge are framing, not pixels.
    if out and len(out[-1]) > 0 and (h - 1) % 4 == 0:
        out.pop()
    for row in out:
        if len(row) > 0 and (w - 1) % 5 == 0:
            row.pop()
    return out
